  check(ss.length === 1 && ss[0].action === 'SESSION_STARTED' && ss[0].outcome === 'SUCCESS' && ss[0].metadata.method === 'password' && ss[0].actor_role === 'TEAM_MEMBER', 'security: a session is recorded once, with its method (never the token)', ss);

