  r = await api('nbdev', 'POST', '/notices', { title: 'NBX CRM maintenance tonight', body: 'The CRM is down from 11 pm to midnight.', category: 'IT_SYSTEM', audienceType: 'ROLE', roles: ['TEAM_MEMBER', 'TEAM_HEAD'], clientRequestId: key() });
